import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

from target import UnifiedMCPGateway

AGY = "Gemini 3.8 Flash (Medium)"


def _envelope(response, status="SUCCESS"):
    return json.dumps({"conversation_id": "c-1", "status": status, "response": response})


def test_codex_jsonl_agent_message_decoder_extracts_payload():
    raw = "\n".join(
        [
            json.dumps({"type": "thread.started", "thread_id": "t-1"}),
            json.dumps({"type": "turn.started"}),
            json.dumps(
                {
                    "type": "item.completed",
                    "item": {"type": "agent_message", "text": json.dumps({"probe": "ok"})},
                }
            ),
            json.dumps({"type": "turn.completed", "usage": {"input_tokens": 1}}),
        ]
    )
    assert UnifiedMCPGateway._decode_model_probe_payload(raw, "codex", "gpt-5") == (
        {"probe": "ok"},
        "codex_jsonl_sequence",
    )


def test_agy_unwraps_success_envelope_with_json_string_response():
    raw = _envelope(json.dumps({"patch": "NO_PATCH"}))
    assert UnifiedMCPGateway._decode_model_probe_payload(raw, "agy", AGY) == (
        {"patch": "NO_PATCH"},
        "agy_json_envelope",
    )


def test_agy_unwraps_mapping_response():
    raw = json.dumps({"status": "SUCCESS", "response": {"patch": "NO_PATCH"}})
    assert UnifiedMCPGateway._decode_model_probe_payload(raw, "agy", AGY) == (
        {"patch": "NO_PATCH"},
        "agy_json_envelope",
    )


def test_agy_fails_closed_on_invalid_envelopes():
    assert UnifiedMCPGateway._decode_model_probe_payload(_envelope(""), "agy", AGY) == (None, None)
    assert UnifiedMCPGateway._decode_model_probe_payload(_envelope("not-json"), "agy", AGY) == (
        None,
        None,
    )
    assert UnifiedMCPGateway._decode_model_probe_payload(
        _envelope(json.dumps({"patch": "bad"}), status="ERROR"), "agy", AGY
    ) == (None, None)


def test_partial_codex_events_rejected():
    partial = json.dumps(
        {"type": "item.completed", "item": {"type": "agent_message", "text": json.dumps({"p": 1})}}
    )
    assert UnifiedMCPGateway._decode_model_probe_payload(partial, "codex", "gpt-5") == (None, None)


def test_direct_json_for_other_providers():
    raw = json.dumps({"probe": "ok"})
    assert UnifiedMCPGateway._decode_model_probe_payload(raw, "gemini", "m") == (
        {"probe": "ok"},
        "direct_json_document",
    )

