import json
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

import target as activation
from target import ActivationManifest, push, readback, render


def _manifest(**overrides):
    base = dict(
        generation="g1",
        activation_state="AUTOMATIC_CAPTURE_READY",
        t_auto="2026-10-12T00:00:00Z",
        excluded_tasks=("task-b", "task-a"),
        readiness_control_token="tok-123",
        repositories=("a/b", "c/d"),
    )
    base.update(overrides)
    return ActivationManifest(**base)


class FakeGh:
    """In-memory stand-in for the gh CLI (variable set / list)."""

    def __init__(self):
        self.state: dict[str, dict[str, str]] = {}
        self.calls: list[list[str]] = []

    def __call__(self, argv, **_kwargs):
        self.calls.append(list(argv[1:]))
        repo = argv[argv.index("--repo") + 1]
        if argv[1:3] == ["variable", "set"]:
            self.state.setdefault(repo, {})[argv[3]] = argv[argv.index("--body") + 1]
            return subprocess.CompletedProcess(argv, 0, "", "")
        if argv[1:3] == ["variable", "list"]:
            rows = [{"name": k, "value": v} for k, v in self.state.get(repo, {}).items()]
            return subprocess.CompletedProcess(argv, 0, json.dumps(rows), "")
        return subprocess.CompletedProcess(argv, 64, "", "unsupported")


def test_variables_are_derived_from_manifest():
    variables = _manifest().variables()
    assert variables[activation.VAR_EXCLUDED_TASKS] == "task-a,task-b"
    assert variables[activation.VAR_T_AUTO] == "2026-10-12T00:00:00Z"
    assert variables[activation.VAR_EXCLUSION_SET_SHA256] == activation.exclusion_set_sha256(
        ["task-b", "task-a"]
    )
    assert set(variables) == set(activation.VARIABLE_NAMES)


def test_render_covers_every_repository():
    rendered = render(_manifest())
    assert set(rendered) == {"a/b", "c/d"}


def test_push_sets_all_variables_and_readback_is_clean():
    gh = FakeGh()
    manifest = _manifest()
    assert push(manifest, runner=gh) == []
    assert len(gh.calls) == 10
    assert all(call[:2] == ["variable", "set"] for call in gh.calls)
    assert readback(manifest, runner=gh) == []


def test_readback_reports_changed_value():
    gh = FakeGh()
    manifest = _manifest()
    push(manifest, runner=gh)
    gh.state["a/b"][activation.VAR_READINESS_CONTROL_TOKEN] = "other"
    drift = readback(manifest, runner=gh)
    assert drift == [
        {
            "repository": "a/b",
            "variable": activation.VAR_READINESS_CONTROL_TOKEN,
            "expected": "tok-123",
            "actual": "other",
        }
    ]


def test_readback_reports_missing_nonempty_variable():
    gh = FakeGh()
    manifest = _manifest()
    push(manifest, runner=gh)
    del gh.state["c/d"][activation.VAR_ACTIVATION_STATE]
    drift = readback(manifest, runner=gh)
    assert len(drift) == 1 and drift[0]["actual"] is None and drift[0]["repository"] == "c/d"


def test_push_reports_set_failures():
    def failing(argv, **_kwargs):
        return subprocess.CompletedProcess(argv, 1, "", " boom ")

    failures = push(_manifest(repositories=("a/b",)), runner=failing)
    assert len(failures) == 5
    assert all(f["stderr"] == "boom" and f["returncode"] == 1 for f in failures)


def test_readback_list_failure_and_unparseable():
    def failing(argv, **_kwargs):
        return subprocess.CompletedProcess(argv, 1, "", "nope")

    def garbage(argv, **_kwargs):
        return subprocess.CompletedProcess(argv, 0, "not json", "")

    m = _manifest(repositories=("a/b",))
    assert readback(m, runner=failing)[0]["error"] == "gh_variable_list_failed"
    assert readback(m, runner=garbage)[0]["error"] == "gh_variable_list_unparseable"

