"""Cross-entrypoint physical mutation-conflict admission (fail-closed evaluator)."""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, Mapping, Optional, Sequence


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _record_value(record: Any, key: str, default: Any = None) -> Any:
    if isinstance(record, Mapping):
        return record.get(key, default)
    return getattr(record, key, default)



def _record_contract(record: Any) -> Any:
    contract = _record_value(record, "contract")
    return contract if contract is not None else record



def _normalized_mutation_paths(record: Any) -> tuple[str, ...]:
    contract = _record_contract(record)
    raw = _record_value(contract, "allowed_files")
    if raw is None:
        raw = _record_value(contract, "allowed_paths")
    if not isinstance(raw, (list, tuple)) or not raw:
        raise ValueError("MUTATION_DOMAIN_INVALID: allowed paths are required")
    normalized: list[str] = []
    for item in raw:
        if not isinstance(item, str) or not item.strip():
            raise ValueError("MUTATION_DOMAIN_INVALID: path is not a string")
        path = item.strip().rstrip("/")
        if not path:
            raise ValueError("MUTATION_DOMAIN_INVALID: path is ambiguous")
        if path.startswith("/") or "\\" in path or "//" in path:
            raise ValueError("MUTATION_DOMAIN_INVALID: path is not repository-relative")
        parts = path.split("/")
        if any(part in {"", ".", ".."} for part in parts):
            raise ValueError("MUTATION_DOMAIN_INVALID: path is ambiguous")
        if path in normalized or any(
            path == other or path.startswith(other + "/") or other.startswith(path + "/")
            for other in normalized
        ):
            raise ValueError("MUTATION_DOMAIN_INVALID: overlapping allowed paths")
        normalized.append(path)
    return tuple(sorted(normalized))



def _validate_mutation_identity(record: Any) -> None:
    task_id = str(_record_value(record, "task_id") or _record_value(_record_contract(record), "task_id") or "").strip()
    if not task_id:
        raise ValueError("MUTATION_IDENTITY_INVALID: task id is missing")
    contract = _record_contract(record)
    controller = str(
        _record_value(record, "controller_worktree")
        or _record_value(contract, "controller_repo_root")
        or ""
    ).strip()
    revision = str(
        _record_value(record, "controller_revision")
        or _record_value(contract, "controller_revision")
        or ""
    ).strip()
    if not controller or not controller.startswith("/") or len(revision) != 40:
        raise ValueError("MUTATION_IDENTITY_INVALID: controller binding is incomplete")
    status = str(_record_value(record, "status") or "").upper()
    lease = _record_value(record, "lease")
    for key in ("attempt_id", "lease_id"):
        value = _record_value(record, key)
        if value is None and key == "lease_id" and isinstance(lease, Mapping):
            value = lease.get(key)
        if value is None and status in {
            "TARGET_LEASED", "WORKER_RUNNING", "WORKER_COMPLETED", "CANDIDATE_CAPTURED", "VERIFIED",
        }:
            raise ValueError(f"MUTATION_IDENTITY_INVALID: {key} is missing")
        if value is not None and not str(value).strip():
            raise ValueError(f"MUTATION_IDENTITY_INVALID: {key} is empty")
        expected = _record_value(record, f"expected_{key}")
        if expected is not None and value != expected:
            raise ValueError(f"MUTATION_IDENTITY_INVALID: {key} is stale")
    for key, value in (
        ("controller_revision", revision),
        ("controller_worktree", controller),
    ):
        expected = _record_value(record, f"expected_{key}")
        if expected is not None and value != expected:
            raise ValueError(f"MUTATION_IDENTITY_INVALID: {key} is stale")

    contract_hash = str(
        _record_value(record, "contract_hash")
        or _record_value(contract, "contract_hash")
        or ""
    ).strip()
    expected_contract_hash = _record_value(record, "expected_contract_hash")
    if expected_contract_hash is not None and contract_hash != expected_contract_hash:
        raise ValueError("MUTATION_IDENTITY_INVALID: contract_hash is stale")

    domain_fingerprint = str(
        _record_value(record, "domain_fingerprint")
        or _record_value(contract, "domain_fingerprint")
        or ""
    ).strip()
    expected_domain_fingerprint = _record_value(record, "expected_domain_fingerprint")
    if expected_domain_fingerprint is not None and domain_fingerprint != str(expected_domain_fingerprint).strip():
        raise ValueError("MUTATION_IDENTITY_INVALID: domain_fingerprint is stale")

    source_identity = str(
        _record_value(record, "source_identity")
        or _record_value(record, "controller_source")
        or _record_value(contract, "source_identity")
        or ""
    ).strip()
    expected_source_identity = _record_value(record, "expected_source_identity")
    if expected_source_identity is not None and source_identity != str(expected_source_identity).strip():
        raise ValueError("MUTATION_IDENTITY_INVALID: source_identity is stale")

    if _record_value(record, "competition_id") is not None:
        raise ValueError("MUTATION_IDENTITY_INVALID: forged competition identity")


MUTATION_CONFLICT_SCHEMA = "nexus.orchestrator.mutation_conflict_admission.v1"
MUTATION_CONFLICT_CLAIM_CEILING = "PHYSICAL_MUTATION_CONFLICT_DISPOSITION_ONLY"

CONFLICT_CLEAR = "CLEAR"
CONFLICT_OVERLAP = "OVERLAP"
CONFLICT_UNKNOWN = "UNKNOWN"
CONFLICT_STALE = "STALE"
CONFLICT_RECONCILE_REQUIRED = "RECONCILE_REQUIRED"

SUPPORTED_MUTATION_LANES = frozenset(
    {"DIRECT_CANONICAL", "DIRECT_DELEGATED", "GOVERNED", "ISOLATED_TARGET", "LOCAL", "WORKING_TREE_ONLY"}
)


def _normalize_mutation_lane(val: Any) -> str:
    if hasattr(val, "value"):
        val = val.value
    raw = str(val or "").strip().upper()
    if "." in raw:
        raw = raw.split(".")[-1]
    if raw in {"WORKING_TREE_ONLY", "GOVERNED"}:
        return "ISOLATED_TARGET"
    return raw


def evaluate_cross_entrypoint_conflict(
    candidate: Any,
    active_writers: Optional[Sequence[Any]] = None,
    *,
    expected_revision: Optional[str] = None,
    inventory_complete: bool = False,
) -> dict[str, Any]:
    """Fail-closed cross-entrypoint conflict admission evaluation.

    Evaluates physical mutation conflict across DIRECT_CANONICAL, DIRECT_DELEGATED,
    GOVERNED (ISOLATED_TARGET), and qualified LOCAL writers.
    Returns structured admission disposition:
      CLEAR, OVERLAP, UNKNOWN, STALE, RECONCILE_REQUIRED
    """
    if candidate is None:
        return {
            "schema": MUTATION_CONFLICT_SCHEMA,
            "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
            "disposition": CONFLICT_UNKNOWN,
            "reason": "CANDIDATE_MISSING",
            "candidate": None,
            "conflicting_writers": [],
        }

    try:
        _validate_mutation_identity(candidate)
    except ValueError as exc:
        return {
            "schema": MUTATION_CONFLICT_SCHEMA,
            "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
            "disposition": CONFLICT_RECONCILE_REQUIRED,
            "reason": f"CANDIDATE_IDENTITY_INVALID: {exc}",
            "candidate": None,
            "conflicting_writers": [],
        }

    cand_contract = _record_contract(candidate)
    cand_task_id = str(
        _record_value(candidate, "task_id")
        or _record_value(cand_contract, "task_id")
        or ""
    )
    cand_attempt_id = str(_record_value(candidate, "attempt_id") or "")
    cand_mode = _normalize_mutation_lane(
        _record_value(cand_contract, "mutation_mode")
        or _record_value(candidate, "mutation_mode")
        or "ISOLATED_TARGET"
    )
    cand_rev = str(
        _record_value(candidate, "controller_revision")
        or _record_value(cand_contract, "controller_revision")
        or ""
    )

    # Validate candidate mutation lane against SUPPORTED_MUTATION_LANES
    if cand_mode not in SUPPORTED_MUTATION_LANES:
        return {
            "schema": MUTATION_CONFLICT_SCHEMA,
            "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
            "disposition": CONFLICT_UNKNOWN,
            "reason": f"UNSUPPORTED_MUTATION_LANE: candidate has {cand_mode!r}",
            "candidate_task_id": cand_task_id,
            "candidate_attempt_id": cand_attempt_id,
            "conflicting_writers": [],
        }

    # expected_revision is required to prevent mutually consistent stale records from passing
    if expected_revision is None or not str(expected_revision).strip():
        return {
            "schema": MUTATION_CONFLICT_SCHEMA,
            "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
            "disposition": CONFLICT_UNKNOWN,
            "reason": "EXPECTED_REVISION_REQUIRED_FOR_ADMISSION",
            "candidate_task_id": cand_task_id,
            "candidate_attempt_id": cand_attempt_id,
            "conflicting_writers": [],
        }
    exp_rev = str(expected_revision).strip()
    if cand_rev != exp_rev:
        return {
            "schema": MUTATION_CONFLICT_SCHEMA,
            "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
            "disposition": CONFLICT_STALE,
            "reason": f"CANDIDATE_REVISION_STALE: expected {exp_rev}, got {cand_rev}",
            "candidate_task_id": cand_task_id,
            "candidate_attempt_id": cand_attempt_id,
            "conflicting_writers": [],
        }

    # Missing/incomplete active-writer inventory must fail closed.  An empty
    # list is only meaningful when the caller can prove all entrypoints were
    # observed; Target-only ownership records are not a complete inventory.
    if active_writers is None:
        return {
            "schema": MUTATION_CONFLICT_SCHEMA,
            "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
            "disposition": CONFLICT_UNKNOWN,
            "reason": "ACTIVE_WRITER_INVENTORY_MISSING",
            "candidate_task_id": cand_task_id,
            "candidate_attempt_id": cand_attempt_id,
            "candidate_mode": cand_mode,
            "conflicting_writers": [],
        }
    if not inventory_complete:
        return {
            "schema": MUTATION_CONFLICT_SCHEMA,
            "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
            "disposition": CONFLICT_UNKNOWN,
            "reason": "CROSS_ENTRYPOINT_INVENTORY_INCOMPLETE",
            "candidate_task_id": cand_task_id,
            "candidate_attempt_id": cand_attempt_id,
            "candidate_mode": cand_mode,
            "observed_writer_count": len(active_writers),
            "conflicting_writers": [],
        }

    cand_unknown = _record_value(candidate, "unknown_effect_refs") or _record_value(
        candidate, "unresolved_effects"
    )
    if cand_unknown:
        return {
            "schema": MUTATION_CONFLICT_SCHEMA,
            "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
            "disposition": CONFLICT_RECONCILE_REQUIRED,
            "reason": "CANDIDATE_UNRESOLVED_PRIOR_EFFECTS",
            "candidate_task_id": cand_task_id,
            "candidate_attempt_id": cand_attempt_id,
            "conflicting_writers": [],
        }

    try:
        cand_paths = _normalized_mutation_paths(candidate)
    except ValueError as exc:
        return {
            "schema": MUTATION_CONFLICT_SCHEMA,
            "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
            "disposition": CONFLICT_RECONCILE_REQUIRED,
            "reason": f"CANDIDATE_PATHS_MALFORMED: {exc}",
            "candidate_task_id": cand_task_id,
            "candidate_attempt_id": cand_attempt_id,
            "conflicting_writers": [],
        }

    conflicting_writers = []
    writers = list(active_writers)
    for writer in writers:
        if writer is None:
            return {
                "schema": MUTATION_CONFLICT_SCHEMA,
                "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
                "disposition": CONFLICT_UNKNOWN,
                "reason": "ACTIVE_WRITER_MISSING_OR_CORRUPT",
                "candidate_task_id": cand_task_id,
                "conflicting_writers": [],
            }

        writer_unknown = _record_value(writer, "unknown_effect_refs") or _record_value(
            writer, "unresolved_effects"
        )
        if writer_unknown:
            return {
                "schema": MUTATION_CONFLICT_SCHEMA,
                "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
                "disposition": CONFLICT_RECONCILE_REQUIRED,
                "reason": "ACTIVE_WRITER_UNRESOLVED_PRIOR_EFFECTS",
                "candidate_task_id": cand_task_id,
                "conflicting_writers": [str(_record_value(writer, "task_id") or "")],
            }

        try:
            _validate_mutation_identity(writer)
        except ValueError as exc:
            return {
                "schema": MUTATION_CONFLICT_SCHEMA,
                "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
                "disposition": CONFLICT_RECONCILE_REQUIRED,
                "reason": f"ACTIVE_WRITER_IDENTITY_INVALID: {exc}",
                "candidate_task_id": cand_task_id,
                "conflicting_writers": [str(_record_value(writer, "task_id") or "")],
            }

        writer_contract = _record_contract(writer)
        writer_task_id = str(
            _record_value(writer, "task_id")
            or _record_value(writer_contract, "task_id")
            or ""
        )
        writer_attempt_id = str(_record_value(writer, "attempt_id") or "")
        writer_mode = _normalize_mutation_lane(
            _record_value(writer_contract, "mutation_mode")
            or _record_value(writer, "mutation_mode")
            or "ISOLATED_TARGET"
        )
        writer_rev = str(
            _record_value(writer, "controller_revision")
            or _record_value(writer_contract, "controller_revision")
            or ""
        )

        # Validate writer mutation lane against SUPPORTED_MUTATION_LANES
        if writer_mode not in SUPPORTED_MUTATION_LANES:
            return {
                "schema": MUTATION_CONFLICT_SCHEMA,
                "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
                "disposition": CONFLICT_UNKNOWN,
                "reason": f"UNSUPPORTED_MUTATION_LANE: writer {writer_task_id} has {writer_mode!r}",
                "candidate_task_id": cand_task_id,
                "conflicting_writers": [writer_task_id],
            }

        if (
            writer_task_id == cand_task_id
            and writer_attempt_id
            and writer_attempt_id == cand_attempt_id
        ):
            continue

        if writer_rev != exp_rev:
            return {
                "schema": MUTATION_CONFLICT_SCHEMA,
                "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
                "disposition": CONFLICT_STALE,
                "reason": f"WRITER_REVISION_STALE: writer {writer_task_id} has {writer_rev}, expected {exp_rev}",
                "candidate_task_id": cand_task_id,
                "conflicting_writers": [writer_task_id],
            }

        if cand_mode == "DIRECT_CANONICAL" and writer_mode == "DIRECT_CANONICAL":
            return {
                "schema": MUTATION_CONFLICT_SCHEMA,
                "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
                "disposition": CONFLICT_OVERLAP,
                "reason": "CONCURRENT_DIRECT_CANONICAL_CONFLICT",
                "candidate_task_id": cand_task_id,
                "conflicting_writers": [writer_task_id],
            }

        try:
            writer_paths = _normalized_mutation_paths(writer)
        except ValueError as exc:
            return {
                "schema": MUTATION_CONFLICT_SCHEMA,
                "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
                "disposition": CONFLICT_RECONCILE_REQUIRED,
                "reason": f"WRITER_PATHS_MALFORMED: {exc}",
                "candidate_task_id": cand_task_id,
                "conflicting_writers": [writer_task_id],
            }

        overlaps = [
            cp
            for cp in cand_paths
            for wp in writer_paths
            if cp == wp or cp.startswith(wp + "/") or wp.startswith(cp + "/")
        ]
        if overlaps:
            conflicting_writers.append(
                {
                    "task_id": writer_task_id,
                    "attempt_id": writer_attempt_id,
                    "mutation_mode": writer_mode,
                    "overlapping_paths": sorted(set(overlaps)),
                }
            )

    if conflicting_writers:
        return {
            "schema": MUTATION_CONFLICT_SCHEMA,
            "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
            "disposition": CONFLICT_OVERLAP,
            "reason": "MUTATION_DOMAINS_OVERLAP",
            "candidate_task_id": cand_task_id,
            "candidate_attempt_id": cand_attempt_id,
            "candidate_mode": cand_mode,
            "conflicting_writers": conflicting_writers,
            "normalized_domain": list(cand_paths),
            "observed_at": _utc_now(),
        }

    return {
        "schema": MUTATION_CONFLICT_SCHEMA,
        "claim_ceiling": MUTATION_CONFLICT_CLAIM_CEILING,
        "disposition": CONFLICT_CLEAR,
        "reason": "DISJOINT_AND_VALID",
        "candidate_task_id": cand_task_id,
        "candidate_attempt_id": cand_attempt_id,
        "candidate_mode": cand_mode,
        "normalized_domain": list(cand_paths),
        "active_writer_count": len(writers),
        "observed_at": _utc_now(),
    }

"""Offline-only audit of GitHub main ruleset snapshot invariants.

This is a diagnostic checker, never a permission, issuer or merge authority.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

CONTEXT = "Nexus Core issue completion"
TRUSTED_APP_ID = 15368


def evaluate(snapshot: object) -> list[str]:
    if not isinstance(snapshot, dict):
        return ["INVALID_SNAPSHOT"]
    failures = []
    if snapshot.get("enforcement") != "active":
        failures.append("RULESET_NOT_ACTIVE")
    if snapshot.get("bypass_actors") != []:
        failures.append("BYPASS_ACTORS_PRESENT")
    if snapshot.get("target") != "branch" or not isinstance(snapshot.get("conditions"), dict):
        failures.append("INVALID_BRANCH_TARGET")
    else:
        refs = snapshot["conditions"].get("ref_name")
        if not isinstance(refs, dict) or not ({ "~DEFAULT_BRANCH", "refs/heads/main" } & set(refs.get("include", []))) or "refs/heads/main" in refs.get("exclude", []):
            failures.append("DEFAULT_BRANCH_NOT_INCLUDED")
    rules = snapshot.get("rules")
    if not isinstance(rules, list):
        rules = []
    if not any(isinstance(rule, dict) and rule.get("type") == "pull_request" for rule in rules):
        failures.append("PULL_REQUEST_RULE_MISSING")
    checks = []
    for rule in rules:
        if isinstance(rule, dict) and rule.get("type") == "required_status_checks":
            params = rule.get("parameters")
            if isinstance(params, dict) and isinstance(params.get("required_status_checks"), list):
                checks.extend(params["required_status_checks"])
    core_checks = [check for check in checks if isinstance(check, dict) and check.get("context") == CONTEXT]
    if not core_checks:
        failures.append("CORE_CHECK_MISSING")
    elif any(check.get("integration_id") is None for check in core_checks):
        failures.append("CORE_CHECK_ISSUER_UNBOUND")
    elif len(core_checks) != 1 or type(core_checks[0].get("integration_id")) is not int or core_checks[0]["integration_id"] != TRUSTED_APP_ID:
        failures.append("CORE_CHECK_WRONG_ISSUER")
    return failures


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("snapshots", nargs="+", help="Local JSON snapshots; never fetched or changed")
    args = parser.parse_args(argv)
    results = []
    for name in args.snapshots:
        try:
            content = json.loads(Path(name).read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            violations = ["SNAPSHOT_UNREADABLE"]
        else:
            violations = evaluate(content)
        results.append({"path": name, "status": "FAIL" if violations else "PASS", "reason_codes": violations})
    failed = any(row["status"] == "FAIL" for row in results)
    print(json.dumps({"status": "FAIL" if failed else "PASS", "snapshots": results}, sort_keys=True))
    return 1 if failed else 0

"""Read-only Gateway source drift analysis (published base vs. loaded git_head)."""

from __future__ import annotations

import subprocess
from collections.abc import Callable
from pathlib import Path
from typing import Any

SCHEMA = "nexus.gateway_source_drift.v1"
DEFAULT_MAIN_REF = "origin/main"
TASK_BINDING_PREFIX = "tasks/"
BEHIND_MAX_COMMITS = 50
BEHIND_MAX_SECONDS = 7 * 24 * 60 * 60
REMEDY = "rebind via #526 governed path; Owner decision"

OK, INFO, WARN, ALERT, PROBE_FAILURE = "OK", "INFO", "WARN", "ALERT", "PROBE_FAILURE"
EXIT_CODES = {OK: 0, INFO: 0, WARN: 1, ALERT: 1, PROBE_FAILURE: 2}
_RANK = {OK: 0, INFO: 1, WARN: 2, ALERT: 3}

# Returns the numbers of open or merged PRs whose head SHA equals the given SHA.
PrHeadLookup = Callable[[str], list[int]]


class ProbeError(Exception):
    def __init__(self, code: str, detail: str) -> None:
        super().__init__(f"{code}: {detail}")
        self.code = code
        self.detail = detail


def _git(repo: Path, *args: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["git", "-C", str(repo), *args],
        check=False,
        capture_output=True,
        text=True,
    )


def _git_out(repo: Path, *args: str, code: str = "GIT_FAILED") -> str:
    result = _git(repo, *args)
    if result.returncode != 0:
        raise ProbeError(code, f"git {' '.join(args)}: {result.stderr.strip()[:300]}")
    return result.stdout


def _has_commit(repo: Path, sha: str) -> bool:
    return _git(repo, "cat-file", "-e", f"{sha}^{{commit}}").returncode == 0


def _resolve_head(repo: Path, head: str, source_repo: str | None) -> None:
    if _has_commit(repo, head):
        return
    if source_repo:
        # Read-only on the source: copies the objects into the analysis clone.
        _git(repo, "fetch", "--quiet", "--no-tags", source_repo, head)
    if not _has_commit(repo, head):
        raise ProbeError(
            "GATEWAY_HEAD_UNRESOLVABLE",
            f"{head} not present in {repo} (source repo: {source_repo or 'none'})",
        )


def _changed_paths(repo: Path, commit: str) -> list[str]:
    out = _git_out(repo, "diff-tree", "-m", "-r", "--no-commit-id", "--name-only", commit)
    return [line for line in out.splitlines() if line]


def analyze(
    repo: Path,
    health: dict[str, Any],
    *,
    main_ref: str = DEFAULT_MAIN_REF,
    source_repo: str | None = None,
    pr_head_lookup: PrHeadLookup | None = None,
) -> dict[str, Any]:
    head = health["git_head"]
    _resolve_head(repo, head, source_repo)
    main = _git_out(
        repo, "rev-parse", "--verify", f"{main_ref}^{{commit}}", code="MAIN_REF_UNRESOLVABLE"
    ).strip()
    base_result = _git(repo, "merge-base", head, main)
    if base_result.returncode != 0 or not base_result.stdout.strip():
        raise ProbeError("NO_PUBLISHED_BASE", f"{head} shares no history with {main_ref}")
    base = base_result.stdout.strip()

    findings: list[dict[str, Any]] = []
    unpublished = _git_out(repo, "rev-list", "--reverse", f"{base}..{head}").split()
    pr_lookup = "NOT_NEEDED"
    if unpublished:
        published_prs: list[int] = []
        if pr_head_lookup is None:
            pr_lookup = "SKIPPED_OFFLINE"
        else:
            published_prs = sorted(pr_head_lookup(head))
            pr_lookup = "MATCHED" if published_prs else "NO_MATCH"
        if published_prs:
            findings.append({
                "code": f"GATEWAY_PUBLISHED_PR_HEAD(#{published_prs[0]})",
                "severity": INFO,
                "pull_requests": published_prs,
            })
        else:
            touched = sorted({p for commit in unpublished for p in _changed_paths(repo, commit)})
            findings.append({
                "code": f"GATEWAY_SOURCE_UNPUBLISHED({len(unpublished)})",
                "severity": ALERT,
                "touched_paths": touched[:100],
                "touched_paths_outside_tasks": [
                    p for p in touched if not p.startswith(TASK_BINDING_PREFIX)
                ][:100],
            })

    behind = int(_git_out(repo, "rev-list", "--count", f"{base}..{main}").strip())
    base_time = int(_git_out(repo, "show", "-s", "--format=%ct", base).strip())
    main_time = int(_git_out(repo, "show", "-s", "--format=%ct", main).strip())
    lag_seconds = main_time - base_time
    if behind:
        reasons = []
        if behind > BEHIND_MAX_COMMITS:
            reasons.append(f"MORE_THAN_{BEHIND_MAX_COMMITS}_COMMITS")
        if lag_seconds > BEHIND_MAX_SECONDS:
            reasons.append("MORE_THAN_7_DAYS")
        if reasons:
            findings.append({
                "code": f"GATEWAY_BEHIND_MAIN({behind})",
                "severity": WARN,
                "reasons": reasons,
                "lag_seconds": lag_seconds,
            })

    verdict = max((f["severity"] for f in findings), key=_RANK.__getitem__, default=OK)
    return {
        "schema": SCHEMA,
        "verdict": verdict,
        "findings": findings,
        "git_head": head,
        "published_base": base,
        "main_ref": main_ref,
        "main_head": main,
        "unpublished_commits": unpublished,
        "pr_head_lookup": pr_lookup,
        "behind_main": behind,
        "lag_seconds": lag_seconds,
        "observed": {
            k: health.get(k)
            for k in (
                "repo_root",
                "repo_head_at_start",
                "repo_head_current",
                "reload_required",
                "server_instance_id",
            )
        },
    }


def summarize(report: dict[str, Any]) -> str:
    codes = ", ".join(f["code"] for f in report["findings"]) or "in sync with main"
    line = f"gateway-source-drift {report['verdict']}: {codes}"
    if report["verdict"] in (WARN, ALERT):
        line += f" -- remedy: {REMEDY}"
    elif report["verdict"] == PROBE_FAILURE:
        line += " -- drift unknown (fail closed)"
    return line
